{
  "probability": 0.96,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Anchor the forecast on the IOM Missing Migrants Project annual Mediterranean fatalities as the reference class with a conservative prior.",
    "Early 2026 data show about 606 deaths/missing through February; continuing at that pace would plausibly exceed 1,000 by May if not offset by major changes.",
    "Key factors include weather-driven risk, rescue-capacity constraints, and reporting/underreporting dynamics, all nudging the total higher.",
    "Historical toll levels around 2,100–2,450 per year support the plausibility of reaching the 1,000-by-May mark, though uncertainty remains."
  ],
  "confidence": "high",
  "narrative": "Using the reference class of annual Mediterranean fatalities and current early-2026 momentum, the posterior probability of reaching 1,000 deaths before May 2026 is 96%. With weather risks, SAR capacity constraints, and reporting dynamics, the outlook remains high but subject to uncertainty from policy and conditions.",
  "justification": {
    "anchor": {
      "probability": 0.25,
      "basis": "reference_class is the IOM Missing Migrants Project annual Mediterranean fatalities; a conservative prior of 0.25 is used to reflect base-rate uncertainty before updating on 2026-specific signals."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean fatalities through February 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths/missing by February implies a pace that could surpass 1,000 by May if sustained; this strongly elevates the probability."
      },
      {
        "factor": "Historical annual Mediterranean toll (2025 baseline ~2,100–2,450)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Long-run patterns show high annual totals, making 1,000-by-May plausible if current momentum persists."
      },
      {
        "factor": "Rescue capacity and policy environment",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Constraints on SAR operations and restrictive policies could raise fatalities by reducing rescue opportunities."
      },
      {
        "factor": "Weather conditions and ongoing shipwreck risk (early 2026)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Hazardous seas and storms contribute to elevated risk of fatalities and can sustain higher totals."
      },
      {
        "factor": "Data reporting completeness and underreporting",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Underreporting by some actors means true tolls could be higher, nudging totals upward toward the threshold."
      }
    ],
    "synthesis_rationale": "The updates collectively push the posterior toward 1,000 deaths by May, with correlations among factors likely reducing the effective independence of signals. Calibration reflects a high-but-not-certainty stance, acknowledging weather, policy dynamics, and reporting noise as the main sources of residual uncertainty."
  }
}

